using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using Frociart;
internal static class ReferenceFormatTests {
 static int checks;static void Check(bool b,string text){if(!b)throw new Exception(text);checks++;}static string Run(Diagram d){var r=new Interpreter(d);for(int i=0;i<500&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Reference program completes: "+r.Error);return r.OutputText;}
 [STAThread]static int Main(string[] args){try{string root=args[0],code="FUNZIONE bump(v: RIF INTERO[])\nv[0]=7\nFINE FUNZIONE\na=[1,2]\nCHIAMA bump(a)\nSTAMPA a";var d=FlowPseudocode.Decode(code);Check(d.Version==3&&d.Functions[0].Parameters[0].ByReference,"Explicit format 3 and RIF signature");Check(Run(d)=="[7, 2]","RIF executes");Check(Run(FlowPseudocode.Decode(FlowPseudocode.Encode(d)))=="[7, 2]","Signature round trip");var library=FunctionTransfer.Export(d,d.Functions[0].Id);Check(library.Version==3&&library.Functions[0].Parameters[0].ByReference,"Function library format 3");var plan=FunctionTransfer.Import(DiagramIO.CreateBlank(),library,library.Functions[0].Id);Check(plan.Project.Version==3&&plan.Project.Functions[0].Parameters[0].ByReference,"Function import preserves reference metadata");var renamed=d.Functions[0].Copy();renamed.Parameters[0].Name="dati";var edited=FunctionEditing.Save(d,renamed,new Dictionary<string,string>{{"v","dati"}});Check(edited.Version==3&&Run(edited)=="[7, 2]","Parameter rename retains reference behavior");
 var downgraded=DiagramIO.Clone(d);downgraded.Version=2;bool rejected=false;try{DiagramIO.EncodeDocument(downgraded);}catch(InvalidDataException){rejected=true;}Check(rejected,"Reference metadata cannot be encoded as an older format");foreach(string broken in new[]{"FUNZIONE f(v: RIF INTERO)\nFINE FUNZIONE\nSTAMPA 1","FUNZIONE f(v: RIF INTERO[])\nFINE FUNZIONE\na=[1]\nCHIAMA f(a[0])","FUNZIONE f(v: RIF INTERO[])\nFINE FUNZIONE\nCHIAMA f(vettore(1))","FUNZIONE f(v: RIF INTERO[])\nv=[1]\nFINE FUNZIONE\na=[2]\nCHIAMA f(a)"}){rejected=false;try{FlowPseudocode.Decode(broken);}catch(FlowPseudocode.ParseError){rejected=true;}Check(rejected,"Scalar/computed/whole-array reference syntax rejected atomically");}
 string xml=File.ReadAllText(Path.Combine(root,"reference-simple.fprg"),Encoding.UTF8);var imported=FlowgorithmImport.DecodeText(xml);Check(imported.Version==3&&imported.Functions[0].Parameters[0].ByReference,"FPRG array parameter imports by reference");var runner=new Interpreter(imported);for(int i=0;i<300&&runner.State!=RuntimeState.Completed&&runner.State!=RuntimeState.Error;i++)runner.Step();Check(runner.State==RuntimeState.Completed&&((VectorValue)runner.Variables["a"]).At(0).ToString()=="7","Imported FPRG changes original element");
 using(var editor=new FunctionEditorDialog(d,d.Functions[0])){Check(editor.Parameters[0].Reference.Checked&&editor.Parameters[0].Reference.Enabled,"Native signature draft retains enabled reference choice");editor.Parameters[0].Array.Checked=false;Check(!editor.Parameters[0].Reference.Checked&&!editor.Parameters[0].Reference.Enabled,"Scalar toggle clears invalid reference choice");editor.Parameters[0].Array.Checked=true;editor.Parameters[0].Reference.Checked=true;editor.Save();Check(editor.EditedProject!=null&&editor.EditedProject.Version==3&&Run(editor.EditedProject)=="[7, 2]","Native signature draft saves reference choice");}
 foreach(string prefix in new[]{"rif\t","ReF   ","RIF \t "}){var spaced=FlowPseudocode.Decode(code.Replace("RIF ",prefix));Check(spaced.Functions[0].Parameters[0].ByReference&&Run(spaced)=="[7, 2]","Whitespace and case in reference prefix");}
 Check(FunctionModel.ProjectVersion(new[]{(FlowFunction)null})==2,"Incomplete draft version helper remains safe");
 var incomplete=d.Functions[0].Copy();incomplete.Parameters=null;Check(FunctionModel.ProjectVersion(new[]{incomplete})==2,"Incomplete parameter list version helper remains safe");
 foreach(var source in new[]{d,imported}){var payload=FlowClipboard.Decode(FlowClipboard.Encode(source));Check(payload.Version==3&&payload.Functions[0].Parameters[0].ByReference,"Clipboard keeps reference mode and explicit version");}
 Console.WriteLine("REFERENCE_FORMAT_PC PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
